pm.test("All items have valid postId, unique id, and required fields", function () {
    const res = pm.response.json();
    const seenIds = new Set();

    res.forEach((item, index) => {
        pm.expect(item.postId, `item[${index}].postId`).to.eql(1);

        pm.expect(item.id, `item[${index}].id`).to.exist;
        pm.expect(item.id, `item[${index}].id`).to.not.be.null;
        pm.expect(seenIds.has(item.id), `duplicate id: ${item.id}`).to.be.false;
        seenIds.add(item.id);

        pm.expect(item.name, `item[${index}].name`).to.be.a("string").and.not.empty;
        pm.expect(item.email, `item[${index}].email`).to.be.a("string").and.include("@");
        pm.expect(item.body, `item[${index}].body`).to.be.a("string").and.not.empty;
    });
});

