// 1. เช็ก Status, Response Time และโครงสร้าง Array
pm.test("Status is 200 OK, fast response, and valid array", function () {
    pm.response.to.have.status(200);
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

// 2. เช็กข้อมูลภายในทุก Object
pm.test("Validate all comment items", function () {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const ids = res.map(item => item.id);

    // เช็กว่า id ไม่ซ้ำกันเลยใน array
    pm.expect(new Set(ids).size, "Duplicate IDs found").to.eql(res.length);

    res.forEach((item, idx) => {
        pm.expect(item.postId, `item[${idx}].postId`).to.eql(1);
        pm.expect(item.id, `item[${idx}].id`).to.be.a("number").and.above(0);
        pm.expect(item.name, `item[${idx}].name`).to.be.a("string").and.not.empty;
        pm.expect(item.email, `item[${idx}].email`).to.be.a("string").and.match(emailRegex);
        pm.expect(item.body, `item[${idx}].body`).to.be.a("string").and.not.empty;
    });
});

